1://! Bounded process I/O and explicit ownership for cache filesystem/transport work.
2://!
3://! Dropping a cache operation kills its owned children. Reaping is delegated to
4://! the runtime only on cancellation; the normal path waits for each child.
5:use anyhow::{Context, Result, ensure};
6:use std::process::{ExitStatus, Stdio};
7:use std::time::Duration;
8:use tokio::io::{AsyncRead, AsyncReadExt, AsyncWriteExt};
9:use tokio::process::{Child, Command};
10:
11:pub(crate) const OUTPUT_LIMIT: usize = 64 * 1024;
12:pub(crate) const COMMAND_TIMEOUT: Duration = Duration::from_secs(60);
13:
14:pub(crate) struct Output {
15:    pub status: ExitStatus,
16:    pub stdout: Vec<u8>,
17:    pub stderr: Vec<u8>,
18:}
19:
20:struct OwnedChild(Option<Child>);
21:
22:impl OwnedChild {
23:    fn spawn(command: &mut Command) -> Result<Self> {
24:        Ok(Self(Some(command.kill_on_drop(true).spawn()?)))
25:    }
26:
27:    fn child(&mut self) -> &mut Child {
28:        self.0.as_mut().expect("child exists until it is reaped")
29:    }
30:
31:    async fn wait(&mut self) -> Result<ExitStatus> {
32:        let status = self.child().wait().await?;
33:        self.0.take();
34:        Ok(status)
35:    }
36:
37:    async fn wait_success(&mut self, label: &str) -> Result<ExitStatus> {
38:        let status = self.wait().await?;
39:        ensure!(status.success(), "{label} exited with {status}");
40:        Ok(status)
41:    }
42:}
43:
44:impl Drop for OwnedChild {
45:    fn drop(&mut self) {
46:        if let Some(mut child) = self.0.take() {
47:            // Send the signal synchronously, before a replacement operation can
48:            // start. Child::wait itself is cancellation safe. Tokio's orphan
49:            // reaper is the fallback if the runtime is already shutting down.
50:            let _ = child.start_kill();
51:            if let Ok(runtime) = tokio::runtime::Handle::try_current() {
52:                runtime.spawn(async move {
53:                    let _ = child.wait().await;
54:                });
55:            }
56:        }
57:    }
58:}
59:
60:async fn read_output(mut stream: impl AsyncRead + Unpin) -> Result<Vec<u8>> {
61:    let mut bytes = Vec::new();
62:    let mut buffer = [0u8; 8192];
63:    loop {
64:        let count = stream.read(&mut buffer).await?;
65:        if count == 0 {
66:            return Ok(bytes);
67:        }
68:        ensure!(
69:            count <= OUTPUT_LIMIT.saturating_sub(bytes.len()),
70:            "cache subprocess output exceeded {OUTPUT_LIMIT} bytes"
71:        );
72:        bytes.extend_from_slice(&buffer[..count]);
73:    }
74:}
75:
76:/// Capture only small command responses. Overflow, timeout, I/O failure and
77:/// caller cancellation all drop the child owner and terminate the process.
78:pub(crate) async fn output(command: &mut Command, deadline: Duration) -> Result<Output> {
79:    command.stdout(Stdio::piped()).stderr(Stdio::piped());
80:    let mut process = OwnedChild::spawn(command)?;
81:    let stdout = process.child().stdout.take().context("missing stdout")?;
82:    let stderr = process.child().stderr.take().context("missing stderr")?;
83:    let (stdout, stderr, status) = tokio::time::timeout(deadline, async {
84:        tokio::try_join!(read_output(stdout), read_output(stderr), process.wait())
85:    })
86:    .await
87:    .context("cache subprocess timed out")??;
88:    Ok(Output {
89:        status,
90:        stdout,
91:        stderr,
92:    })
93:}
94:
95:/// Copy the send stream with Tokio's fixed-size I/O buffer. No detached copier
96:/// task or whole-stream capture exists. An early failed child aborts the peer.
97:pub(crate) async fn pipeline(
98:    sender: &mut Command,
99:    receiver: &mut Command,
