389:    /// Create a Btrfs cache subvolume on Btrfs. Ordinary filesystems use a
390:    /// regular directory; Btrfs failures are never interpreted as fallback.
391:    async fn create_btrfs_subvolume(path: &Path) -> Result<()> {
392:        let existing = match tokio::fs::symlink_metadata(path).await {
393:            Ok(metadata) => {
394:                anyhow::ensure!(
395:                    metadata.is_dir() && !metadata.file_type().is_symlink(),
396:                    "cache path is not a directory: {}",
397:                    path.display()
398:                );
399:                true
400:            }
401:            Err(error) if error.kind() == std::io::ErrorKind::NotFound => false,
402:            Err(error) => return Err(error.into()),
403:        };
404:        let probe = if existing {
405:            path
406:        } else {
407:            path.parent()
408:                .context("Cache subvolume path has no parent")?
409:        };
410:        if !is_btrfs_filesystem(probe)? {
411:            tokio::fs::create_dir_all(path)
412:                .await
413:                .context("Failed to create ordinary cache directory")?;
414:            return Ok(());
415:        }
416:        if existing {
417:            let output = managed_process::output(
418:                tokio::process::Command::new("btrfs")
419:                    .args(["property", "get", "-ts"])
420:                    .arg(path)
421:                    .arg("ro"),
422:                managed_process::COMMAND_TIMEOUT,
423:            )
424:            .await
425:            .context("Failed to execute btrfs command")?;
426:            if output.status.success()
427:                && String::from_utf8_lossy(&output.stdout).trim() == "ro=false"
428:            {
429:                Self::enable_compression(path).await?;
430:                return Ok(());
431:            }
432:
433:            let stderr = String::from_utf8_lossy(&output.stderr);
434:            anyhow::bail!(
435:                "existing cache path is not a usable Btrfs subvolume ({}): {}",
436:                path.display(),
437:                stderr.trim()
438:            );
439:        }
440:
441:        let output = managed_process::output(
442:            tokio::process::Command::new("btrfs")
443:                .args(["subvolume", "create"])
444:                .arg(path),
445:            managed_process::COMMAND_TIMEOUT,
446:        )
447:        .await
448:        .context("Failed to execute btrfs command")?;
449:
450:        if !output.status.success() {
451:            let stderr = String::from_utf8_lossy(&output.stderr);
452:            anyhow::bail!("btrfs subvolume create failed: {}", stderr);
453:        } else {
454:            Self::enable_compression(path).await?;
455:        }
456:
457:        Ok(())
458:    }
459:
460:    async fn enable_compression(path: &Path) -> Result<()> {
461:        let output = managed_process::output(
462:            tokio::process::Command::new("btrfs")
463:                .args(["property", "set"])
464:                .arg(path)
465:                .args(["compression", "zstd"]),
466:            managed_process::COMMAND_TIMEOUT,
467:        )
468:        .await
469:        .context("Failed to execute btrfs property command")?;
470:        if !output.status.success() {
471:            anyhow::bail!(
472:                "failed to enable Btrfs zstd compression for {}: {}",
473:                path.display(),
474:                String::from_utf8_lossy(&output.stderr).trim()
475:            );
476:        }
477:        Ok(())
478:    }
479:
480:    /// Open or create the cache root and its five category subvolumes.
481:    pub async fn new(cache_dir: PathBuf) -> Result<Self> {
482:        let snapshot_config = SnapshotConfig {
483:            snapshot_dir: cache_dir
484:                .parent()
485:                .unwrap_or(Path::new("/var/lib/op-dbus"))
486:                .join("@cache-snapshots"),
487:            max_snapshots: std::env::var("OPDBUS_MAX_CACHE_SNAPSHOTS")
488:                .ok()
489:                .and_then(|s| s.parse().ok())
490:                .unwrap_or(24),
491:            prefix: std::env::var("OPDBUS_CACHE_SNAPSHOT_PREFIX")
492:                .unwrap_or_else(|_| "SNP-cache".to_string()),
493:        };
494:        anyhow::ensure!(
495:            snapshot_config.max_snapshots > 0,
496:            "Cache rotation requires positive retention"
497:        );
498:        let snapshot_manager = SnapshotManager::new(cache_dir.clone(), snapshot_config);
499:
500:        // Ensure parent directory exists (not as subvolume)
501:        if let Some(parent) = cache_dir.parent() {
502:            tokio::fs::create_dir_all(parent).await?;
503:        }
504:
505:        // Each category remains a Btrfs subvolume on Btrfs. A snapshot of the
506:        // root alone omits their contents; SnapshotManager snapshots the set.
507:        Self::create_btrfs_subvolume(&cache_dir).await?;
508:        for category in ["embeddings", "blocks", "queries", "diffs", "kv"] {
509:            Self::create_btrfs_subvolume(&cache_dir.join(category)).await?;
510:        }
511:
512:        // Create regular directories within subvolumes
513:        tokio::fs::create_dir_all(cache_dir.join("embeddings/vectors")).await?;
514:        tokio::fs::create_dir_all(cache_dir.join("blocks/by-number")).await?;
515:        tokio::fs::create_dir_all(cache_dir.join("blocks/by-hash")).await?;
516:
517:        // Create CozoDB in-memory index for embeddings (replaces SQLite)
518:        let index = CozoGraphShuttle::new_in_memory()
519:            .map_err(|e| anyhow::anyhow!("Failed to create CozoDB index: {e}"))?;
520:
521:        // Each cache owns a fresh, bounded derived index. Full input texts and
522:        // keys are never retained; schema positions stay compatible.
523:        index
524:            .run_query(
525:                r#":create embedding_cache {
526:                text_hash: String
527:                =>
528:                text: String default "",
529:                vector_file: String default "",
530:                created_at: String default "",
531:                accessed_at: String default "",
532:                access_count: Int default 1,
533:                vector_size: Int default 0
534:            }"#,
535:                None,
536:            )
537:            .map_err(|error| anyhow::anyhow!("Failed to create embedding cache index: {error}"))?;
538:
539:        // Create the kv_cache relation for the generic key-value API.
540:        index
541:            .run_query(
542:                r#":create kv_cache {
543:                key_hash: String
544:                =>
545:                key: String default "",
546:                file_path: String default "",
547:                created_at: String default "",
548:                accessed_at: String default "",
549:                access_count: Int default 1,
550:                data_size: Int default 0
551:            }"#,
552:                None,
553:            )
554:            .map_err(|error| anyhow::anyhow!("Failed to create KV cache index: {error}"))?;
555:
556:        // Detect NUMA topology
557:        let numa_topology = NumaTopology::detect()?;
558:        let placement_strategy = Self::determine_placement_strategy(numa_topology.nodes());
559:        let memory_policy = Self::determine_memory_policy();
560:
561:        // Record the initial permitted placement; execution applies it to
562:        // transport children, never to this shared async worker.
563:        let allowed_cpus = NumaOptimizer::current_cpu_affinity();
564:        let cpu_affinity = Self::select_placement_node(
565:            &numa_topology,
566:            &placement_strategy,
567:            0,
568:            allowed_cpus.as_deref(),
569:            numa_topology.current_node(),
570:        )
571:        .map(|node| node.cpu_list)
572:        .unwrap_or_default();
573:
574:        // Initialize the in-memory fast path with configurable limits.
575:        let max_entries = Self::configured_limit(
576:            "OPDBUS_CACHE_MEMORY_MAX_ENTRIES",
577:            DEFAULT_MEMORY_MAX_ENTRIES,
578:        )?;
579:        let max_bytes =
580:            Self::configured_limit("OPDBUS_CACHE_MEMORY_MAX_BYTES", DEFAULT_MEMORY_MAX_BYTES)?;
581:        let index_max_entries =
582:            Self::configured_limit("OPDBUS_CACHE_INDEX_MAX_ENTRIES", DEFAULT_INDEX_MAX_ENTRIES)?;
583:        let max_payload_bytes =
584:            Self::configured_limit("OPDBUS_CACHE_MAX_PAYLOAD_BYTES", DEFAULT_MAX_PAYLOAD_BYTES)?;
585:        let max_embedding_dimensions = Self::configured_limit(
586:            "OPDBUS_CACHE_MAX_EMBEDDING_DIMENSIONS",
587:            DEFAULT_MAX_EMBEDDING_DIMENSIONS,
588:        )?;
589:        let memory_cache = MemoryCache::new(max_entries, max_bytes);
590:
591:        Ok(Self {
592:            cache_dir,
593:            index,
594:            index_max_entries,
595:            index_lru: Mutex::new(std::collections::VecDeque::new()),
596:            operation: Mutex::new(()),
597:            total_accesses: std::sync::atomic::AtomicU64::new(0),
598:            max_payload_bytes,
599:            max_embedding_dimensions,
600:            snapshot_manager,
601:            numa_topology,
602:            placement_strategy,
603:            memory_policy,
604:            cpu_affinity,
605:            current_node_index: AtomicUsize::new(0),
606:            numa_stats: Mutex::new(NumaStats::new()),
607:            memory_cache,
608:        })
609:    }
