611:    fn determine_placement_strategy(numa_nodes: &HashMap<u32, NumaNode>) -> CachePlacementStrategy {
612:        let default_choice = if numa_nodes.is_empty() {
613:            "disabled".to_string()
614:        } else {
615:            "local".to_string()
616:        };
617:
618:        let placement = std::env::var("OPDBUS_CACHE_PLACEMENT")
619:            .unwrap_or(default_choice)
620:            .to_lowercase();
621:
622:        match placement.as_str() {
623:            "round-robin" | "round_robin" | "roundrobin" => CachePlacementStrategy::RoundRobin,
624:            "most-memory" | "most_memory" | "mostmemory" => CachePlacementStrategy::MostMemory,
625:            "disabled" => CachePlacementStrategy::Disabled,
626:            "local" | "local-node" | "local_node" => {
627:                if numa_nodes.is_empty() {
628:                    CachePlacementStrategy::Disabled
629:                } else {
630:                    CachePlacementStrategy::LocalNode
631:                }
632:            }
633:            other => {
634:                warn!(
635:                    "Unknown OPDBUS_CACHE_PLACEMENT value '{}', defaulting to {}",
636:                    other,
637:                    if numa_nodes.is_empty() {
638:                        "disabled"
639:                    } else {
640:                        "local"
641:                    }
642:                );
643:                if numa_nodes.is_empty() {
644:                    CachePlacementStrategy::Disabled
645:                } else {
646:                    CachePlacementStrategy::LocalNode
647:                }
648:            }
649:        }
650:    }
