652:    fn determine_memory_policy() -> MemoryPolicy {
653:        match std::env::var("OPDBUS_CACHE_MEMORY_POLICY") {
654:            Ok(value) => {
655:                let value_lower = value.to_lowercase();
656:                if let Some(rest) = value_lower.strip_prefix("bind:") {
657:                    let nodes = Self::parse_node_list(rest);
658:                    if nodes.is_empty() {
659:                        warn!("OPDBUS_CACHE_MEMORY_POLICY=bind but no NUMA nodes listed");
660:                        MemoryPolicy::Default
661:                    } else {
662:                        MemoryPolicy::Bind(nodes)
663:                    }
664:                } else if let Some(rest) = value_lower.strip_prefix("preferred:") {
665:                    if rest.trim().is_empty() {
666:                        MemoryPolicy::Preferred(None)
667:                    } else {
668:                        match rest.trim().parse::<u32>() {
669:                            Ok(node) => MemoryPolicy::Preferred(Some(node)),
670:                            Err(e) => {
671:                                warn!(
672:                                    "Failed to parse preferred NUMA node '{}': {}",
673:                                    rest.trim(),
674:                                    e
675:                                );
676:                                MemoryPolicy::Default
677:                            }
678:                        }
679:                    }
680:                } else if value_lower == "preferred" {
681:                    MemoryPolicy::Preferred(None)
682:                } else if let Some(rest) = value_lower.strip_prefix("interleave:") {
683:                    let nodes = Self::parse_node_list(rest);
684:                    if nodes.is_empty() {
685:                        warn!("OPDBUS_CACHE_MEMORY_POLICY=interleave but no NUMA nodes listed");
686:                        MemoryPolicy::Default
687:                    } else {
688:                        MemoryPolicy::Interleave(nodes)
689:                    }
690:                } else if value_lower == "default" || value_lower.is_empty() {
691:                    MemoryPolicy::Default
692:                } else {
693:                    warn!(
694:                        "Unknown OPDBUS_CACHE_MEMORY_POLICY value '{}', using default",
695:                        value
696:                    );
697:                    MemoryPolicy::Default
698:                }
699:            }
700:            Err(_) => MemoryPolicy::Default,
701:        }
702:    }
703:
704:    fn parse_node_list(list: &str) -> Vec<u32> {
705:        list.split(',')
706:            .filter_map(|s| {
707:                let trimmed = s.trim();
708:                if trimmed.is_empty() {
709:                    None
710:                } else {
711:                    match trimmed.parse::<u32>() {
712:                        Ok(value) => Some(value),
713:                        Err(e) => {
714:                            warn!("Invalid NUMA node id '{}': {}", trimmed, e);
715:                            None
716:                        }
717:                    }
718:                }
719:            })
720:            .collect()
721:    }
