723:    fn select_numa_node(&self, operation: &str) -> Option<NumaNode> {
724:        if matches!(self.placement_strategy, CachePlacementStrategy::Disabled) {
725:            return None;
726:        }
727:        let mut topology = self.numa_topology.clone();
728:        if let Err(error) = topology.refresh() {
729:            warn!(
730:                "NUMA topology refresh failed for {operation}; retaining last snapshot: {error:#}"
731:            );
732:        }
733:        let allowed_cpus = NumaOptimizer::current_cpu_affinity();
734:        let index = if matches!(self.placement_strategy, CachePlacementStrategy::RoundRobin) {
735:            self.current_node_index.fetch_add(1, Ordering::Relaxed)
736:        } else {
737:            0
738:        };
739:        let selection = Self::select_placement_node(
740:            &topology,
741:            &self.placement_strategy,
742:            index,
743:            allowed_cpus.as_deref(),
744:            topology.current_node(),
745:        );
746:        if let Some(node) = &selection {
747:            debug!(
748:                "NUMA node {} selected for {} (memory={} MB, distances={:?})",
749:                node.node_id,
750:                operation,
751:                node.memory_free_kb / 1024,
752:                node.distance_to_nodes
753:            );
754:        } else {
755:            debug!(
756:                "No NUMA node selected for {} (strategy={:?})",
757:                operation, self.placement_strategy
758:            );
759:        }
760:
761:        selection
762:    }
763:
764:    fn select_placement_node(
765:        topology: &NumaTopology,
766:        strategy: &CachePlacementStrategy,
767:        index: usize,
768:        allowed_cpus: Option<&[u32]>,
769:        current_node: Option<u32>,
770:    ) -> Option<NumaNode> {
771:        if matches!(strategy, CachePlacementStrategy::Disabled) {
772:            return None;
773:        }
774:        let nodes: Vec<_> = topology
775:            .node_ids()
776:            .into_iter()
777:            .filter_map(|id| topology.get_node(id))
778:            .filter(|node| {
779:                allowed_cpus
780:                    .is_none_or(|allowed| node.cpu_list.iter().any(|cpu| allowed.contains(cpu)))
781:            })
782:            .collect();
783:        if nodes.is_empty() {
784:            return None;
785:        }
786:        let selected = match strategy {
787:            CachePlacementStrategy::LocalNode => nodes
788:                .iter()
789:                .copied()
790:                .find(|node| Some(node.node_id) == current_node)
791:                .unwrap_or(nodes[0]),
792:            CachePlacementStrategy::RoundRobin => nodes[index % nodes.len()],
793:            CachePlacementStrategy::MostMemory => nodes
794:                .iter()
795:                .copied()
796:                .min_by_key(|node| (std::cmp::Reverse(node.memory_free_kb), node.node_id))?,
797:            CachePlacementStrategy::Disabled => return None,
798:        };
799:        let mut selected = selected.clone();
800:        if let Some(allowed) = allowed_cpus {
801:            selected.cpu_list.retain(|cpu| allowed.contains(cpu));
802:        }
803:        Some(selected)
804:    }
