816:    fn lock_operation(&self) -> Result<(std::sync::MutexGuard<'_, ()>, CacheFileLock)> {
817:        use std::os::unix::fs::OpenOptionsExt;
818:        let guard = self
819:            .operation
820:            .lock()
821:            .map_err(|_| anyhow::anyhow!("cache operation lock poisoned"))?;
822:        let file = std::fs::OpenOptions::new()
823:            .read(true)
824:            .write(true)
825:            .create(true)
826:            .truncate(false)
827:            .mode(0o600)
828:            .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC)
829:            .open(self.cache_dir.join(".cache.lock"))?;
830:        anyhow::ensure!(
831:            file.metadata()?.is_file(),
832:            "cache lock is not a regular file"
833:        );
834:        loop {
835:            if unsafe { libc::flock(file.as_raw_fd(), libc::LOCK_EX) } == 0 {
836:                break;
837:            }
838:            let error = std::io::Error::last_os_error();
839:            if error.kind() != std::io::ErrorKind::Interrupted {
840:                return Err(error).context("locking cache files");
841:            }
842:        }
843:        Ok((guard, CacheFileLock(file)))
844:    }
