866:    fn file_metadata(path: &Path) -> Result<Option<std::fs::Metadata>> {
867:        match std::fs::symlink_metadata(path) {
868:            Ok(metadata) => {
869:                anyhow::ensure!(
870:                    metadata.is_file() && !metadata.file_type().is_symlink(),
871:                    "cache payload is not a regular file: {}",
872:                    path.display()
873:                );
874:                Ok(Some(metadata))
875:            }
876:            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(None),
877:            Err(error) => Err(error).with_context(|| format!("reading {}", path.display())),
878:        }
879:    }
880:
881:    fn open_payload(path: &Path) -> Result<std::fs::File> {
882:        use std::os::unix::fs::OpenOptionsExt;
883:        let file = std::fs::OpenOptions::new()
884:            .read(true)
885:            .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC)
886:            .open(path)?;
887:        anyhow::ensure!(
888:            file.metadata()?.is_file(),
889:            "cache payload is not a regular file"
890:        );
891:        Ok(file)
892:    }
893:
894:    fn validate_payload_size(&self, bytes: usize) -> Result<()> {
895:        anyhow::ensure!(
896:            bytes <= self.max_payload_bytes,
897:            "cache payload exceeds OPDBUS_CACHE_MAX_PAYLOAD_BYTES ({})",
898:            self.max_payload_bytes
899:        );
900:        Ok(())
901:    }
902:
903:    fn read_payload(&self, path: &Path) -> Result<Vec<u8>> {
904:        use std::io::Read;
905:        let mut file = Self::open_payload(path)?;
906:        let length =
907:            usize::try_from(file.metadata()?.len()).context("cache payload size overflow")?;
908:        self.validate_payload_size(length)?;
909:        // Allocate from a checked file length, not an untrusted encoded length.
910:        // Reject growth instead of allocating again if another writer ignores
911:        // the cache's file lock.
912:        let mut bytes = vec![0; length];
913:        file.read_exact(&mut bytes)
914:            .with_context(|| format!("reading cache payload {}", path.display()))?;
915:        let mut extra = [0];
916:        anyhow::ensure!(
917:            file.read(&mut extra)? == 0,
918:            "cache payload changed size while reading"
919:        );
920:        Ok(bytes)
921:    }
922:
923:    fn touch_payload(path: &Path) -> Result<FileStamp> {
924:        let file = Self::open_payload(path)?;
925:        file.set_times(std::fs::FileTimes::new().set_modified(std::time::SystemTime::now()))?;
926:        Ok(FileStamp::from_metadata(&file.metadata()?))
927:    }
928:
929:    fn write_payload(path: &Path, bytes: &[u8]) -> Result<FileStamp> {
930:        use std::io::Write;
931:        use std::os::unix::fs::OpenOptionsExt;
932:        let parent = path.parent().context("cache payload has no parent")?;
933:        std::fs::create_dir_all(parent)?;
934:        let temporary = parent.join(format!(".cache-{}.tmp", uuid::Uuid::new_v4()));
935:        let result = (|| {
936:            let mut file = std::fs::OpenOptions::new()
937:                .write(true)
938:                .create_new(true)
939:                .mode(0o600)
940:                .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC)
941:                .open(&temporary)?;
942:            file.write_all(bytes)?;
943:            file.sync_all()?;
944:            let stamp = FileStamp::from_metadata(&file.metadata()?);
945:            std::fs::rename(&temporary, path)?;
946:            std::fs::File::open(parent)?.sync_all()?;
947:            Ok(stamp)
948:        })();
949:        if result.is_err() {
950:            let _ = std::fs::remove_file(&temporary);
951:        }
952:        result
953:    }
954:
955:    fn decode_embedding(&self, bytes: &[u8]) -> Result<Vec<f32>> {
956:        use bincode::Options;
957:        let header: [u8; 8] = bytes
958:            .get(..8)
959:            .context("truncated embedding length")?
960:            .try_into()
961:            .expect("eight-byte slice");
962:        let dimensions =
963:            usize::try_from(u64::from_le_bytes(header)).context("embedding dimension overflow")?;
964:        anyhow::ensure!(
965:            dimensions <= self.max_embedding_dimensions,
966:            "embedding exceeds OPDBUS_CACHE_MAX_EMBEDDING_DIMENSIONS ({})",
967:            self.max_embedding_dimensions
968:        );
969:        let expected = dimensions
970:            .checked_mul(std::mem::size_of::<f32>())
971:            .and_then(|size| size.checked_add(8))
972:            .context("embedding length overflow")?;
973:        anyhow::ensure!(
974:            bytes.len() == expected,
975:            "embedding payload length does not match dimensions"
976:        );
977:        self.validate_payload_size(bytes.len())?;
978:        bincode::DefaultOptions::new()
979:            .with_fixint_encoding()
980:            .reject_trailing_bytes()
981:            .with_limit(self.max_payload_bytes as u64)
982:            .deserialize(bytes)
983:            .context("Failed to deserialize cached embedding")
984:    }
985:
986:    fn validate_embedding(&self, vector: &[f32]) -> Result<usize> {
987:        anyhow::ensure!(
988:            vector.len() <= self.max_embedding_dimensions,
989:            "embedding exceeds OPDBUS_CACHE_MAX_EMBEDDING_DIMENSIONS ({})",
990:            self.max_embedding_dimensions
991:        );
992:        let bytes = vector
993:            .len()
994:            .checked_mul(std::mem::size_of::<f32>())
995:            .and_then(|bytes| bytes.checked_add(8))
996:            .context("embedding size overflow")?;
997:        self.validate_payload_size(bytes)?;
998:        Ok(bytes)
999:    }
1000:
1001:    fn forget_index(&self, embedding: bool, hash: &str) -> Result<()> {
1002:        let query = if embedding {
1003:            "?[text_hash] <- [[$hash]] :rm embedding_cache { text_hash }"
1004:        } else {
1005:            "?[key_hash] <- [[$hash]] :rm kv_cache { key_hash }"
1006:        };
1007:        self.index
1008:            .run_query(query, Some(serde_json::json!({"hash": hash})))
1009:            .map_err(|error| anyhow::anyhow!("cache index removal failed: {error}"))?;
1010:        self.index_lru
1011:            .lock()
1012:            .map_err(|_| anyhow::anyhow!("cache index LRU poisoned"))?
1013:            .retain(|entry| entry.embedding != embedding || entry.hash != hash);
1014:        Ok(())
1015:    }
1016:
1017:    fn record_index(&self, embedding: bool, hash: &str, size: usize) -> Result<()> {
1018:        if embedding {
1019:            self.total_accesses.fetch_add(1, Ordering::Relaxed);
1020:        }
1021:        if self.index_max_entries == 0 {
1022:            return Ok(());
1023:        }
1024:        let mut order = self
1025:            .index_lru
1026:            .lock()
1027:            .map_err(|_| anyhow::anyhow!("cache index LRU poisoned"))?;
1028:        let existing_position = order
1029:            .iter()
1030:            .position(|entry| entry.embedding == embedding && entry.hash == hash);
1031:        if existing_position.is_none() {
1032:            while order.len() >= self.index_max_entries {
1033:                let old = order.front().context("empty cache index eviction")?;
1034:                let query = if old.embedding {
1035:                    "?[text_hash] <- [[$hash]] :rm embedding_cache { text_hash }"
1036:                } else {
1037:                    "?[key_hash] <- [[$hash]] :rm kv_cache { key_hash }"
1038:                };
1039:                self.index
1040:                    .run_query(query, Some(serde_json::json!({"hash": old.hash})))
1041:                    .map_err(|error| anyhow::anyhow!("cache index eviction failed: {error}"))?;
1042:                order.pop_front();
1043:            }
1044:        }
1045:
1046:        let now = chrono::Utc::now().to_rfc3339();
1047:        // The bounded LRU already owns these fixed-size fields. Avoid parsing
1048:        // another Cozo query on every warm read just to increment a counter.
1049:        let existing = existing_position.and_then(|position| order.get(position));
1050:        let count = existing.map_or(1, |entry| entry.access_count.saturating_add(1));
1051:        let created = existing.map_or_else(|| now.clone(), |entry| entry.created_at.clone());
1052:        let file = if embedding {
1053:            format!("{hash}.vec")
1054:        } else {
1055:            format!("kv/{hash}.dat")
1056:        };
1057:        let query = if embedding {
1058:            r#"?[text_hash, text, vector_file, created_at, accessed_at, access_count, vector_size]
1059:                <- [[$hash, "", $file, $created, $now, $count, $size]]
1060:                :put embedding_cache { text_hash => text, vector_file, created_at, accessed_at, access_count, vector_size }"#
1061:        } else {
1062:            r#"?[key_hash, key, file_path, created_at, accessed_at, access_count, data_size]
1063:                <- [[$hash, "", $file, $created, $now, $count, $size]]
1064:                :put kv_cache { key_hash => key, file_path, created_at, accessed_at, access_count, data_size }"#
1065:        };
1066:        self.index.run_query(query, Some(serde_json::json!({
1067:            "hash": hash, "file": file, "created": created, "now": now, "count": count, "size": size,
1068:        }))).map_err(|error| anyhow::anyhow!("cache index write failed: {error}"))?;
1069:        if let Some(position) = existing_position {
1070:            order.remove(position);
1071:        }
1072:        order.push_back(IndexEntry {
1073:            embedding,
1074:            hash: hash.to_owned(),
1075:            access_count: count,
1076:            created_at: created,
1077:        });
1078:        Ok(())
1079:    }
1080:
1081:    fn get_embedding_locked(&self, hash: &str) -> Result<Option<Vec<f32>>> {
1082:        let path = self.embedding_path(hash);
1083:        let key = format!("emb:{hash}");
1084:        let Some(metadata) = Self::file_metadata(&path)? else {
1085:            self.memory_cache.remove(&key);
1086:            self.forget_index(true, hash)?;
1087:            return Ok(None);
1088:        };
1089:        self.validate_payload_size(
1090:            usize::try_from(metadata.len()).context("cache payload size overflow")?,
1091:        )?;
1092:        let stamp = FileStamp::from_metadata(&metadata);
1093:        let cached = self.memory_cache.get_with_stamp(&key, Some(stamp));
1094:        let warm = cached.is_some();
1095:        let bytes = match cached {
1096:            Some(bytes) => bytes,
1097:            None => self.read_payload(&path)?,
1098:        };
1099:        let vector = self.decode_embedding(&bytes)?;
1100:        let stamp = Self::touch_payload(&path)?;
1101:        self.record_index(true, hash, vector.len())?;
1102:        // Avoid a second copy on a warm hit.
1103:        if warm {
1104:            self.memory_cache.set_stamp(&key, stamp);
1105:        } else {
1106:            self.memory_cache.put_slice(&key, &bytes, stamp);
1107:        }
1108:        Ok(Some(vector))
1109:    }
1110:
1111:    fn save_embedding_locked(&self, hash: &str, vector: &[f32]) -> Result<()> {
1112:        self.validate_embedding(vector)?;
1113:        let bytes = bincode::serialize(vector)?;
1114:        let key = format!("emb:{hash}");
1115:        self.memory_cache.remove(&key);
1116:        let stamp = Self::write_payload(&self.embedding_path(hash), &bytes)?;
1117:        self.record_index(true, hash, vector.len())?;
1118:        if self.memory_cache.admits(key.len(), bytes.len()) {
1119:            self.memory_cache.put_with_stamp(key, bytes, Some(stamp));
1120:        }
1121:        Ok(())
1122:    }
1123:
1124:    /// Compute outside the storage lock, then recheck before committing so a
1125:    /// concurrent put/compute wins without being overwritten by stale work.
1126:    pub fn get_or_embed<F>(&self, text: &str, compute_fn: F) -> Result<Vec<f32>>
1127:    where
1128:        F: FnOnce(&str) -> Result<Vec<f32>>,
1129:    {
1130:        let hash = self.hash_text(text);
1131:        {
1132:            let _guard = self.lock_operation()?;
1133:            if let Some(vector) = self.get_embedding_locked(&hash)? {
1134:                return Ok(vector);
1135:            }
1136:        }
1137:        let vector = compute_fn(text)?;
1138:        self.validate_embedding(&vector)?;
1139:        let _guard = self.lock_operation()?;
1140:        if let Some(current) = self.get_embedding_locked(&hash)? {
1141:            return Ok(current);
1142:        }
1143:        self.save_embedding_locked(&hash, &vector)?;
1144:        Ok(vector)
1145:    }
1146:
1147:    pub fn get_embedding(&self, text: &str) -> Result<Option<Vec<f32>>> {
1148:        let _guard = self.lock_operation()?;
1149:        self.get_embedding_locked(&self.hash_text(text))
1150:    }
1151:
1152:    pub fn put_embedding(&self, text: &str, vector: &[f32]) -> Result<()> {
1153:        self.validate_embedding(vector)?;
1154:        let _guard = self.lock_operation()?;
1155:        self.save_embedding_locked(&self.hash_text(text), vector)
1156:    }
1157:
1158:    fn get_raw_locked(&self, hash: &str) -> Result<Option<Vec<u8>>> {
1159:        let path = self.kv_path(hash);
1160:        let key = format!("kv:{hash}");
1161:        let Some(metadata) = Self::file_metadata(&path)? else {
1162:            self.memory_cache.remove(&key);
1163:            self.forget_index(false, hash)?;
1164:            return Ok(None);
1165:        };
1166:        self.validate_payload_size(
1167:            usize::try_from(metadata.len()).context("cache payload size overflow")?,
1168:        )?;
1169:        let stamp = FileStamp::from_metadata(&metadata);
1170:        if let Some(data) = self.memory_cache.get_with_stamp(&key, Some(stamp)) {
1171:            let stamp = Self::touch_payload(&path)?;
1172:            self.record_index(false, hash, data.len())?;
1173:            self.memory_cache.set_stamp(&key, stamp);
1174:            return Ok(Some(data));
1175:        }
1176:        let data = self.read_payload(&path)?;
1177:        let stamp = Self::touch_payload(&path)?;
1178:        self.record_index(false, hash, data.len())?;
1179:        self.memory_cache.put_slice(&key, &data, stamp);
1180:        Ok(Some(data))
1181:    }
1182:
1183:    /// Async API compatibility with bounded synchronous file transactions:
1184:    /// no owned payload is queued in an unbounded blocking-task backlog.
1185:    pub async fn get_raw(&self, key: &str) -> Result<Option<Vec<u8>>> {
1186:        let _guard = self.lock_operation()?;
1187:        self.get_raw_locked(&self.hash_key(key))
1188:    }
1189:
1190:    pub async fn put_raw(&self, key: &str, data: &[u8]) -> Result<()> {
1191:        self.validate_payload_size(data.len())?;
1192:        let hash = self.hash_key(key);
1193:        let _guard = self.lock_operation()?;
