551:    /// Estimate time savings from caching this workflow
552:    fn estimate_time_savings(&self, pattern: &WorkflowPattern) -> u64 {
553:        // Assume 40% cache hit rate on subsequent executions
554:        // and 60% latency reduction when cached
555:        let expected_future_calls = pattern.call_count * 2; // Extrapolate
556:        let cache_hit_savings = (pattern.avg_latency_ms as f64 * 0.6) as u64;
557:        let hit_rate = 0.4;
558:
559:        (expected_future_calls as f64 * cache_hit_savings as f64 * hit_rate) as u64
560:    }
