562:    /// Calculate confidence score for promotion
563:    fn calculate_confidence(&self, pattern: &WorkflowPattern) -> f64 {
564:        let recency_days = (chrono::Utc::now().timestamp() - pattern.last_called) as f64 / 86400.0;
565:        let frequency_score =
566:            (pattern.call_count as f64 / self.config.promotion_threshold as f64).min(2.0) / 2.0;
567:        let recency_score = (1.0 - recency_days / 7.0).max(0.0);
568:        let length_score = if pattern.agent_sequence.len() >= 2 && pattern.agent_sequence.len() <= 5
569:        {
570:            1.0
571:        } else {
572:            0.7
573:        };
574:
575:        (frequency_score * 0.4 + recency_score * 0.3 + length_score * 0.3).min(1.0)
576:    }
