435:static TRANSFERS: LazyLock<Arc<Semaphore>> = LazyLock::new(|| Arc::new(Semaphore::new(2)));
436:
437:static CLEANUP_FAILED: AtomicBool = AtomicBool::new(false);
438:
439:pub(crate) async fn transfer_permit() -> Result<OwnedSemaphorePermit> {
440:    let permit = TRANSFERS.clone().acquire_owned().await?;
441:    anyhow::ensure!(
442:        !CLEANUP_FAILED.load(Ordering::Acquire),
443:        "temporary cache cleanup previously failed; inspect logged paths before restarting transport"
444:    );
445:    Ok(permit)
446:}
447:
448:/// Owns only a directory created by this operation. A committed receive can
449:/// relinquish ownership; source snapshots and partial receives are removed.
450:pub(crate) struct TemporarySet {
451:    path: Option<PathBuf>,
452:    permit: Option<OwnedSemaphorePermit>,
453:}
454:
455:impl TemporarySet {
456:    pub(crate) fn create(path: PathBuf, permit: OwnedSemaphorePermit) -> Result<Self> {
457:        // Synchronous create closes the cancellation gap between mkdir and
458:        // registering ownership; existing destinations are never adopted.
459:        std::fs::create_dir(&path)?;
460:        Ok(Self {
461:            path: Some(path),
462:            permit: Some(permit),
463:        })
464:    }
465:
466:    pub(crate) fn path(&self) -> &Path {
467:        self.path.as_deref().expect("live temporary set")
468:    }
469:
470:    pub(crate) fn preserve(mut self) {
471:        self.path.take();
472:    }
473:
474:    pub(crate) async fn cleanup(mut self) -> Result<()> {
475:        let result = cleanup_owned_set(self.path()).await;
476:        if result.is_ok() {
477:            self.path.take();
478:        }
479:        result
480:    }
481:}
482:
483:impl Drop for TemporarySet {
484:    fn drop(&mut self) {
485:        let Some(path) = self.path.take() else {
486:            return;
487:        };
488:        let permit = self.permit.take();
489:        if let Ok(runtime) = tokio::runtime::Handle::try_current() {
490:            runtime.spawn(async move {
491:                let _permit = permit;
492:                // A cancelled send/receive child was signalled before this
493:                // guard drops. Retry briefly if its kernel work is draining.
494:                for attempt in 0..3 {
495:                    match cleanup_owned_set(&path).await {
496:                        Ok(()) => return,
497:                        Err(error) if attempt == 2 => { CLEANUP_FAILED.store(true, Ordering::Release); tracing::error!(path = %path.display(), %error, "temporary cache set cleanup failed"); },
498:                        Err(_) => tokio::time::sleep(std::time::Duration::from_millis(100)).await,
499:                    }
500:                }
501:            });
502:        } else {
503:            CLEANUP_FAILED.store(true, Ordering::Release);
504:            tracing::error!(path = %path.display(), "runtime stopped before temporary cache set cleanup; recovery required");
505:        }
506:    }
507:}
508:
509:async fn cleanup_owned_set(path: &Path) -> Result<()> {
510:    if !path.try_exists()? {
511:        return Ok(());
512:    }
513:    let metadata = std::fs::symlink_metadata(path)?;
514:    anyhow::ensure!(
515:        metadata.is_dir() && !metadata.file_type().is_symlink(),
516:        "invalid temporary set"
517:    );
518:    // Never recursively remove arbitrary files or unexpected nested objects.
519:    for entry in std::fs::read_dir(path)? {
520:        let entry = entry?;
521:        let name = entry.file_name();
522:        anyhow::ensure!(
523:            name == ".complete" || CACHE_MEMBERS.iter().any(|member| name == *member),
524:            "unexpected object in temporary cache set: {}",
525:            entry.path().display()
526:        );
527:        anyhow::ensure!(
528:            !entry.file_type()?.is_symlink(),
529:            "symlink in temporary cache set"
530:        );
531:    }
532:    let marker = path.join(".complete");
533:    if marker.try_exists()? {
534:        std::fs::remove_file(marker)?;
535:    }
536:    for member in CACHE_MEMBERS.iter().rev() {
537:        let member = path.join(member);
538:        if !member.try_exists()? {
539:            continue;
540:        }
541:        SnapshotManager::ensure_subvolume(&member, false).await?;
542:        let output = managed_process::output(
543:            Command::new("btrfs")
544:                .args(["subvolume", "delete"])
545:                .arg(&member),
546:            COMMAND_TIMEOUT,
547:        )
